import{_ as r,C as a,o as s,c as n,ag as t,E as i}from"./chunks/framework.CtWPcAmt.js";const m=JSON.parse('{"title":"Selling Existing Products","description":"","frontmatter":{},"headers":[],"relativePath":"catalog/selling-existing-products.md","filePath":"catalog/selling-existing-products.md","lastUpdated":1786088921000}'),l={name:"catalog/selling-existing-products.md"};function c(d,o,p,u,g,h){const e=a("ImagePopup");return s(),n("div",null,[o[0]||(o[0]=t('<h1 id="selling-existing-products" tabindex="-1">Selling Existing Products <a class="header-anchor" href="#selling-existing-products" aria-label="Permalink to &quot;Selling Existing Products&quot;">​</a></h1><p>Not every product has to be built from scratch. If an item already exists in the marketplace catalog, a seller can list <strong>their own offer</strong> on it — their price, stock, condition, and description — without recreating the product. This is the &quot;Sell as Yours&quot; flow.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>How to find an existing product to sell</li><li>Every field on the &quot;Sell as Yours&quot; form</li><li>How offers differ by product type, and how they get approved</li></ul></div><h2 id="finding-a-product-to-sell" tabindex="-1">Finding a product to sell <a class="header-anchor" href="#finding-a-product-to-sell" aria-label="Permalink to &quot;Finding a product to sell&quot;">​</a></h2><p>From the <strong>List Your Product</strong> launcher, choose <strong>Search Products</strong> (or open <strong>Catalog → Products</strong> and start the create flow). Search the marketplace catalog by name — results appear after a few characters, each showing the product&#39;s image, name, and price.</p>',5)),i(e,{src:"/images/selling-existing-products/search.png",alt:"Search existing catalog products"}),o[1]||(o[1]=t('<p>On the product you want, select <strong>Sell as Yours</strong> to open the offer form.</p><div class="info custom-block"><p class="custom-block-title">When you can&#39;t sell one</p><p>You&#39;ll be stopped if the admin has disabled assigning products, if the product&#39;s type isn&#39;t one you&#39;re allowed to sell, or if you&#39;re <strong>already selling</strong> that product.</p></div><h2 id="the-sell-as-yours-form" tabindex="-1">The &quot;Sell as Yours&quot; form <a class="header-anchor" href="#the-sell-as-yours-form" aria-label="Permalink to &quot;The &quot;Sell as Yours&quot; form&quot;">​</a></h2><p>You&#39;re not editing the product itself — only your <strong>offer</strong> on it. The <strong>General</strong> panel holds the core fields, with the catalog product shown on the right for reference:</p><ul><li><strong>Condition</strong> — <strong>New</strong> or <strong>Old</strong>.</li><li><strong>Price</strong> — your selling price (for simple, virtual, and downloadable products).</li><li><strong>Description</strong> — a short description of your offer, up to <strong>300 characters</strong> (a live counter shows how many you&#39;ve used).</li></ul><p>An <strong>Inventories</strong> panel lets you set stock <strong>per inventory source</strong> (for simple and virtual products). The product&#39;s images and other catalog details are shared from the existing product, so you don&#39;t re-upload them for a simple offer.</p><h3 id="by-product-type" tabindex="-1">By product type <a class="header-anchor" href="#by-product-type" aria-label="Permalink to &quot;By product type&quot;">​</a></h3><ul><li><strong>Configurable</strong> — pick which variants you&#39;ll sell; for each, set its <strong>price</strong>, <strong>quantities</strong> per source, <strong>description</strong>, and <strong>images</strong>.</li><li><strong>Downloadable</strong> — add your own <strong>downloadable links</strong> (title, price, downloads limit, file or URL) and <strong>samples</strong>.</li></ul><h2 id="saving-and-approval" tabindex="-1">Saving and approval <a class="header-anchor" href="#saving-and-approval" aria-label="Permalink to &quot;Saving and approval&quot;">​</a></h2><p>Save the offer as a <strong>draft</strong> to finish later, or <strong>Submit</strong> it for approval. Like any listing, an assigned product enters the <a href="/catalog/product-management#drafts-submission-and-approval">approval flow</a> — the admin reviews it, and once approved it appears on the storefront under your store at your price. You can revisit the offer any time to adjust price, stock, or condition.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Reselling is the fastest way to grow a catalog around popular products. To assign <strong>many</strong> products at once, use <strong>Sell Catalog Products</strong> in <a href="/catalog/bulk-upload">Bulk Upload</a>.</p></div>',11))])}const y=r(l,[["render",c]]);export{m as __pageData,y as default};
